# Using your API wrapper from Part 1, conduct systematic experiments comparing different
# prompting strategies on two of the following tasks:

# 1. Question Answering: Answer factual questions given a context paragraph.
# 2. Reasoning Problems: Solve puzzles or logic problems.

# For each task, implement and compare:
# • Zero-shot prompting — provide only the task instruction with no examples
# • Few-shot prompting — include 2–3 examples in the prompt
# • Chain-of-thought prompting — instruct the model to reason step-by-step
# • Your own variation — design a fourth prompting approach (e.g., role-playing, tructured output format, self-consistency)

# Experiment Requirements:
# • Use at least 10 test inputs per task (provide your test data in the submission)
# • Keep temperature and other parameters constant across comparisons (report your settings)
# • Record the full prompt used for each technique
# • Track token usage and/or response time for each approach

import time
from api_basics import query_llm

def main():
    # Define test inputs for Question Answering
    qa_inputs = [
        {"context": "During the 1918 influenza pandemic, the virus infected roughly one-third of the world's population and killed an estimated 50 million people. Unusually, it was most lethal to healthy adults aged 20-40 rather than the very young or elderly.", "question": "Why was the 1918 flu pandemic unusual compared to typical influenza outbreaks?"},
        {"context": "Octopuses have three hearts: two branchial hearts pump blood to the gills, while the third systemic heart pumps oxygenated blood to the rest of the body. The systemic heart actually stops beating when the octopus swims, which is why they prefer crawling.", "question": "Why do octopuses prefer crawling over swimming?"},
        {"context": "The Voyager 1 spacecraft, launched in 1977, entered interstellar space in August 2012 after crossing the heliopause at roughly 121 AU from the Sun. Despite being over 14 billion miles away, it still communicates with Earth using a 23-watt transmitter — about the power of a refrigerator light bulb.", "question": "How powerful is the transmitter Voyager 1 uses to communicate with Earth from interstellar space?"},
        {"context": "In 2016, Google DeepMind's AlphaGo defeated world champion Lee Sedol in Go, a game with more possible board positions than atoms in the observable universe. The key breakthrough was combining Monte Carlo tree search with deep neural networks trained through both supervised learning on expert games and reinforcement learning from self-play.", "question": "What techniques allowed AlphaGo to master a game considered too complex for brute-force computation?"},
        {"context": "The platypus is one of only five species of monotremes — mammals that lay eggs. Males possess venomous spurs on their hind legs capable of causing severe pain in humans. The platypus also hunts underwater using electroreception, detecting the electric fields generated by the muscle contractions of its prey.", "question": "How does the platypus locate prey while hunting underwater?"},
        {"context": "The Library of Alexandria, founded in the 3rd century BCE, is estimated to have held between 40,000 and 400,000 scrolls at its peak. Contrary to popular belief, it was not destroyed in a single catastrophic fire but declined gradually over several centuries due to reduced funding, political purges, and multiple smaller conflicts.", "question": "What actually caused the decline of the Library of Alexandria?"},
        {"context": "CRISPR-Cas9 gene editing works by using a guide RNA sequence to direct the Cas9 enzyme to a specific location in an organism's DNA. The enzyme then cuts both strands of the double helix, and the cell's natural repair mechanisms can be harnessed to delete, replace, or insert new genetic material at the cut site.", "question": "What role does the guide RNA play in the CRISPR-Cas9 editing process?"},
        {"context": "Venus rotates on its axis in the opposite direction to most planets in the solar system, meaning the Sun rises in the west and sets in the east. A single Venusian day (one full rotation) takes about 243 Earth days, which is actually longer than its year of 225 Earth days.", "question": "How does Venus's rotation period compare to its orbital period, and what consequence does this have?"},
        {"context": "The Dunning-Kruger effect, described in a 1999 paper by psychologists David Dunning and Justin Kruger, found that people with limited competence in a domain tend to overestimate their own ability, while genuine experts tend to underestimate theirs. The proposed mechanism is that the skills needed to produce correct judgments are the same skills needed to recognize correct judgments.", "question": "According to Dunning and Kruger, why do less competent individuals overestimate their ability?"},
        {"context": "Tardigrades, also known as water bears, can survive extreme conditions including temperatures from -272C to 150C, pressures six times greater than the deepest ocean trench, radiation hundreds of times the lethal human dose, and even the vacuum of outer space. They achieve this through cryptobiosis, a state where metabolism drops to nearly zero.", "question": "What biological mechanism allows tardigrades to survive conditions that would kill virtually all other organisms?"}
    ]

    # Define test inputs for Reasoning Problems
    reasoning_inputs = [
        {"problem": "A bat and a ball cost $1.10 together. The bat costs $1.00 more than the ball. How much does the ball cost?"},
        {"problem": "If it takes 5 machines 5 minutes to make 5 widgets, how long would it take 100 machines to make 100 widgets?"},
        {"problem": "A woman has two coins that total 30 cents. One of them is not a nickel. What are the two coins?"},
        {"problem": "You're in a room with three light switches, each controlling one of three light bulbs in the next room. You can only enter the next room once. How do you determine which switch controls which bulb?"},
        {"problem": "A man is looking at a photograph. Someone asks him, 'Whose picture are you looking at?' He replies: 'Brothers and sisters I have none, but that man's father is my father's son.' Whose picture is the man looking at?"},
        {"problem": "You have 12 identical-looking coins. One is counterfeit and is either heavier or lighter than the rest. Using a balance scale only 3 times, how do you identify the counterfeit coin and determine if it's heavier or lighter?"},
        {"problem": "Three people check into a hotel room that costs $30. They each pay $10. Later, the manager realizes the room should have been $25 and gives $5 to the bellboy to return. The bellboy keeps $2 and gives $1 back to each guest. Now each guest has paid $9 (totaling $27), and the bellboy has $2. That's $29. Where did the missing dollar go?"},
        {"problem": "You're on a game show. There are three doors: behind one is a car, behind the others are goats. You pick door 1. The host, who knows what's behind each door, opens door 3 to reveal a goat. Should you switch to door 2 or stick with door 1?"},
        {"problem": "A lily pad doubles in size every day. If it takes 48 days for the lily pad to cover an entire lake, how many days does it take to cover half the lake?"},
        {"problem": "Five pirates must divide 100 gold coins. They vote on proposals in order of seniority; a proposal passes if it gets at least 50% of votes. If a proposal fails, the proposer is thrown overboard. What should the most senior pirate propose to maximize their gold while surviving?"}
    ]

    # Define prompting strategies for Question Answering
    qa_strategies = {
        "zero_shot": lambda inp: f"Given the following passage, extract the relevant information and answer the question. Limit your response to 50 words.\nPassage: {inp['context']}\nQuery: {inp['question']}",
        "few_shot": lambda inp: f"Task: Extractive question answering. Given a passage, answer the query using only information present in the text.\n\nExample 1:\nPassage: The capital of France is Paris.\nQuery: What is the capital of France?\nAnswer: Paris.\n\nExample 2:\nPassage: The largest mammal is the blue whale.\nQuery: What is the largest mammal?\nAnswer: The blue whale.\n\nNow answer the following. Limit your response to 50 words.\nPassage: {inp['context']}\nQuery: {inp['question']}",
        "chain_of_thought": lambda inp: f"Given the passage below, identify the key claims, isolate the relevant evidence, and derive your answer step-by-step. Limit your response to 50 words.\nPassage: {inp['context']}\nQuery: {inp['question']}\nReasoning:",
        "role_playing": lambda inp: f"You are an information retrieval system optimized for precision. Given a passage and a query, return only the most relevant answer supported by the text. Limit your response to 50 words.\nPassage: {inp['context']}\nQuery: {inp['question']}"
    }

    # Define prompting strategies for Reasoning Problems
    reasoning_strategies = {
        "zero_shot": lambda inp: f"Solve the following problem. \n{inp['problem']}",
        "few_shot": lambda inp: f"Here are some examples of solving reasoning problems:\nExample 1:\nProblem: If all cats are animals and all animals are living things, are all cats living things?\nAnswer: Yes\nExample 2:\nProblem: If a car travels 60 miles in 1 hour, how far does it travel in 30 minutes?\nAnswer: 30 miles\nNow, solve the following problem. \n{inp['problem']}",
        "chain_of_thought": lambda inp: f"Solve the following problem step-by-step. \n{inp['problem']}\nAnswer:",
        "role_playing": lambda inp: f"Solve the following problem. Explain to a 10-year-old. \n{inp['problem']}"
    }

    # Run experiments for Question Answering
    for strategy_name, strategy_func in qa_strategies.items():
        print(f"Testing {strategy_name} strategy for Question Answering...")
        for inp in qa_inputs:
            prompt = strategy_func(inp)
            start_time = time.time()
            response, usage = query_llm(prompt)
            end_time = time.time()
            print(f"Prompt:\n{prompt}\nResponse:\n{response}\nTime taken: {end_time - start_time:.2f} seconds")
            print(f"Tokens used: {usage.get('total_tokens', 'N/A')} (prompt: {usage.get('prompt_tokens', 'N/A')}, completion: {usage.get('completion_tokens', 'N/A')})\n")

    # Run experiments for Reasoning Problems
    for strategy_name, strategy_func in reasoning_strategies.items():
        print(f"Testing {strategy_name} strategy for Reasoning Problems...")
        for inp in reasoning_inputs:
            prompt = strategy_func(inp)
            start_time = time.time()
            response, usage = query_llm(prompt)
            end_time = time.time()
            print(f"Prompt:\n{prompt}\nResponse:\n{response}\nTime taken: {end_time - start_time:.2f} seconds")
            print(f"Tokens used: {usage.get('total_tokens', 'N/A')} (prompt: {usage.get('prompt_tokens', 'N/A')}, completion: {usage.get('completion_tokens', 'N/A')})\n")


if __name__ == "__main__":
    main()

